rowdata.pyStepsJavaSource:
// default SuccessIndicator to 0
tools.putParamValue("SuccessIndicator", "0");
ClipboardPage primaryPage = tools.getPrimaryPage();

// if workPage parameter blank, use primary page name
if (pega_rules_default.IsParamBlank(tools, "workPage"))		
{
	if (primaryPage != null)
	{
		if (primaryPage.getName().equals(""))
		{
			// The primary page must have a name, and we prefer pyWorkPage
			if (tools.findPage("pyWorkPage") == null)
				primaryPage.rename("pyWorkPage");
			else
			{
				// We won't overwrite pyWorkPage, so we must abort
				tools.putParamValue("SuccessIndicator", "-10");
				tools.putParamValue("FailureInfo", "The page being locked has no name, and 'pyWorkPage' is already in use.");
				nextBlock = "***";	
				return true;											
			}
		}
		workPage = primaryPage.getName();
	}
	else
	{
		// We must open onto a named page, and we prefer pyWorkPage
		if (tools.findPage("pyWorkPage") != null)
		{
			// We won't overwrite pyWorkPage, so we must abort
			tools.putParamValue("SuccessIndicator", "-10");
			tools.putParamValue("FailureInfo", "No page name was passed into WorkLock, and 'pyWorkPage' is already in use.");
			nextBlock = "***";	
			return true;											
		}
		workPage = "pyWorkPage";
	}
}
else
	workPage = tools.getParamValue("workPage");

// if workHandle parameter blank, use primary page handle
if (pega_rules_default.IsParamBlank(tools, "workHandle"))
{
	if (primaryPage != null)
	{
		if (primaryPage.getProperty(".pyTemporaryObject").toBoolean())
		{
			// The work object is temporary; it doesn't get locked
			nextBlock = "T";
			return true;
		}
		else
		{
			String workHandle = primaryPage.getString(".pzInsKey");
			if (workHandle == null || workHandle.equals(""))
			{
				// If pzInsKey hasn't been computed yet, it is a new page and cannot be locked.
				tools.putParamValue("SuccessIndicator", "-10");
				tools.putParamValue("FailureInfo", "A new page cannot be locked; it must be saved first.");
				nextBlock = "***";					
				return true;	
			}
			else
				tools.putParamValue("workHandle", workHandle);
		}
	}
	else
	{
		// No primary page and no handle specified; we are sunk!!!
		tools.putParamValue("SuccessIndicator", "-10");
		tools.putParamValue("FailureInfo", "No work object information was passed in to WorkLock");
		nextBlock = "***";
		return true;
	}
}

// if coverPage parameter blank, use pyWorkCover
if (pega_rules_default.IsParamBlank(tools, "coverPage") 
   && tools.getParamAsBoolean(PropertyInfo.TYPE_TRUEFALSE, "workOnly") == false)
{
	String strCoverPage = "pyWorkCover";
	ClipboardPage pyWorkCover = tools.findPage("pyWorkCover");
	if (pyWorkCover == null && !workPage.equals("pyWorkPage"))
	{
		// Let's double-check that the cover isn't, in fact, currently residing in pyWorkPage
		// if the user supplied a different page name
		ClipboardPage pyWorkPage = tools.findPage("pyWorkPage");
		if (pyWorkPage != null && pega_rules_utilities.isOrInheritsFrom(tools, pyWorkPage, "Work-Cover-"))
		{
			String workHandle = tools.getParamValue("workHandle");
			ClipboardProperty coveredKeys = pyWorkPage.getProperty(".pxCoveredInsKeys");
			if (pega_rules_utilities.IsInPropertyList(workHandle, coveredKeys))
			{
				// Yes, this is the cover we want.  We can use pyWorkPage because the primary work
				// object is on a different page
				strCoverPage = "pyWorkPage";
			}
		}
	}
	tools.putParamValue("coverPage", strCoverPage);
}

String strWorstMessage = tools.getActivityStatus().getWorstMessage();
String workKey = tools.getParamValue("workHandle");

// We need to distinguish between an open failure and a lock failure.
String msgName = tools.getActivityStatus().getWorstMessageName();
if (msgName.equals("Database-Instance-NotFound"))
{
	// Unable to open the work object
	tools.putParamValue("SuccessIndicator", "-1");
	tools.putParamValue("FailureInfo", tools.getRuleMessage("WorkLock-WorkOpenFail\t" + workKey + "\t" + strWorstMessage));
}
else if (msgName.equals("Database-Authorization-NoOpenAccess"))
{
	// Security violation in opening this work object
	tools.putParamValue("SuccessIndicator", "-2");
	tools.putParamValue("FailureInfo", tools.getRuleMessage("WorkLock-WorkOpenFail\t" + workKey + "\t" + strWorstMessage));
}
else if (msgName.equals("Database-LockFailure-LockHeldByAnother"))
{
	// Unable to lock the work object
	tools.putParamValue("SuccessIndicator", "-3");
	tools.putParamValue("FailureInfo", tools.getRuleMessage("WorkLock-WorkLockFail\t" + workKey + "\t" + strWorstMessage));			

	boolean bDisplayLockInfo = tools.getParamAsBoolean(PropertyInfo.TYPE_TRUEFALSE, "DisplayLockInfo");
	if (bDisplayLockInfo == true)
	{
		pega_rules_utilities.callActivity(myStepPage, "DisplayLockInfo", tools.getParameterPage());
	}
}
else if (msgName.equals("Database-Authorization-NoModifyAccess"))
{	
  String strMessage = tools.getStepPage().getMessagesAll();
	// Security violation to lock due to no modify access
	tools.putParamValue("SuccessIndicator", "-4");
	tools.putParamValue("FailureInfo", tools.getRuleMessage("WorkLock-WorkLockFail\t" + workKey + "\t" + strWorstMessage) + "\t" + strMessage);			
}
else
{
	tools.putParamValue("SuccessIndicator", "-10");
	tools.putParamValue("FailureInfo", strWorstMessage);
}

// First remove any locks we've already taken out
ClipboardPage pgWork = tools.findPage(workPage);
pega_rules_utilities.callActivity(pgWork, "WorkUnlock", tools.getParameterPage());

String strWorstMessage = tools.getActivityStatus().getWorstMessage();
String workKey = tools.getParamValue("workHandle");

// We need to distinguish between an open failure and a lock failure.
String msgName = tools.getActivityStatus().getWorstMessageName();
if (msgName.equals("Database-Instance-NotFound"))
{
	// Unable to open the cover object
	tools.putParamValue("SuccessIndicator", "-5");
	tools.putParamValue("FailureInfo", tools.getRuleMessage("WorkLock-CoverOpenFail\t" + coverHandle + "\t" + workKey + "\t" + strWorstMessage));

	// We are going to add a message to the workpage about it
	pgWork.getProperty(".pxCoverInsKey").addMessage(tools.getParamValue("FailureInfo"));
}
else if (msgName.equals("Database-Authorization-NoOpenAccess"))
{
	// Security violation to open the cover
	tools.putParamValue("SuccessIndicator", "-6");
	tools.putParamValue("FailureInfo", tools.getRuleMessage("WorkLock-CoverOpenFail\t" + coverHandle + "\t" + workKey + "\t" + strWorstMessage));			

	// We are going to add a message to the workpage about it
	pgWork.getProperty(".pxCoverInsKey").addMessage(tools.getParamValue("FailureInfo"));
}
else if (msgName.equals("Database-LockFailure-LockHeldByAnother"))
{
	// Unable to lock the cover object
	tools.putParamValue("SuccessIndicator", "-7");
	tools.putParamValue("FailureInfo", tools.getRuleMessage("WorkLock-CoverLockFail\t" + coverHandle + "\t" + workKey + "\t" + strWorstMessage));						
	boolean bDisplayLockInfo = tools.getParamAsBoolean(PropertyInfo.TYPE_TRUEFALSE, "DisplayLockInfo");
	if (bDisplayLockInfo == true)
	{
		// When we show a work object in the LockInfo harness, we must first move
		// it to the work page
		pgWork.replace(myStepPage);
		myStepPage.removeFromClipboard();
		pega_rules_utilities.callActivity(pgWork, "DisplayLockInfo", tools.getParameterPage());
	}
}
else if (msgName.equals("Database-Authorization-NoModifyAccess"))
{
	// Security violation to lock due to no modify access
	tools.putParamValue("SuccessIndicator", "-8");
	tools.putParamValue("FailureInfo", tools.getRuleMessage("WorkLock-CoverLockFail\t" + coverHandle + "\t" + workKey + "\t" + strWorstMessage));						

	// We are going to add a message to the workpage about it
	pgWork.getProperty(".pxCoverInsKey").addMessage(tools.getParamValue("FailureInfo"));
}
else
{
	tools.putParamValue("SuccessIndicator", "-10");
	tools.putParamValue("FailureInfo", strWorstMessage);

	// We are going to add a message to the workpage about it
	pgWork.getProperty(".pxCoverInsKey").addMessage(tools.getParamValue("FailureInfo"));			
}

// Lock the work object's pxLockHandle
boolean bReleaseOnCommit = !tools.getParamAsBoolean(PropertyInfo.TYPE_TRUEFALSE, "releaseLockManually");
String strLockHandle = myStepPage.getString(".pxLockHandle");
if (strLockHandle.length() > 0) 
{			
	try 
	{ 
		ClipboardPage pgLockInfo = tools.createPage("System-Locks", "");
		if (!tools.getDatabase().getLockManager().lock(strLockHandle, bReleaseOnCommit, pgLockInfo))
		{
			// Failed to lock, -9 is the indicator that the lock string was something else
			pgLockInfo.rename("LockInfo");
			tools.putParamValue("SuccessIndicator", "-9");	
			tools.putParamValue("FailureInfo", tools.getRuleMessage("Database-LockFailure-LockHeldByAnother\t" + strLockHandle + "\t" + pgLockInfo.getString("pxCreateOperator")));					
			tools.getStepStatus().add(ProcessingStatus.SEVERITY_FAIL, "Locked", "could not lock " + strLockHandle);

			// remove locks already taken
			pega_rules_utilities.callActivity(myStepPage, "WorkUnlock", tools.getParameterPage());

			boolean bDisplayLockInfo = tools.getParamAsBoolean(PropertyInfo.TYPE_TRUEFALSE, "DisplayLockInfo");
			if (bDisplayLockInfo == true)
			{			
				pega_rules_utilities.callActivity(myStepPage, "DisplayLockInfo", tools.getParameterPage());
			}
			nextBlock = "***";
		}
	} catch (DatabaseException e) {
		tools.putParamValue("SuccessIndicator", "-10");
		tools.putParamValue("FailureInfo", "Failure while trying to lock " + strLockHandle + " was: " + e.getMessage());
		nextBlock = "***";									
	}
}

// Since we didn't try to lock the cover, we must have failed to open it

// First remove any locks we've already taken out
ClipboardPage pgWork = tools.findPage(workPage);
pega_rules_utilities.callActivity(pgWork, "WorkUnlock", tools.getParameterPage());

String strWorstMessage = tools.getActivityStatus().getWorstMessage();
String workKey = tools.getParamValue("workHandle");

// We need to distinguish between an open failure and a lock failure.
String msgName = tools.getActivityStatus().getWorstMessageName();
if (msgName.equals("Database-Instance-NotFound"))
{
	// Unable to open the cover object
	tools.putParamValue("SuccessIndicator", "-5");
	tools.putParamValue("FailureInfo", tools.getRuleMessage("WorkLock-CoverOpenFail\t" + coverHandle + "\t" + workKey + "\t" + strWorstMessage));

	// We are going to add a message to the workpage about it
	pgWork.getProperty(".pxCoverInsKey").addMessage(tools.getParamValue("FailureInfo"));
}
else if (msgName.equals("Database-Authorization-NoOpenAccess"))
{
	// Security violation to open the cover
	tools.putParamValue("SuccessIndicator", "-6");
	tools.putParamValue("FailureInfo", tools.getRuleMessage("WorkLock-CoverOpenFail\t" + coverHandle + "\t" + workKey + "\t" + strWorstMessage));			

	// We are going to add a message to the workpage about it
	pgWork.getProperty(".pxCoverInsKey").addMessage(tools.getParamValue("FailureInfo"));
}
else
{
	tools.putParamValue("SuccessIndicator", "-10");
	tools.putParamValue("FailureInfo", strWorstMessage);		

	// We are going to add a message to the workpage about it
	pgWork.getProperty(".pxCoverInsKey").addMessage(tools.getParamValue("FailureInfo"));			
}
